  ((select id from questions where external_key = 'read-2a'), 'Comparing a treatment only against no intervention can overstate its true effect, so placebo-controlled comparison is necessary.', '1', NULL, true, 1, ('[{"dimensionKey":"verbal","points":1},{"dimensionKey":"reading","points":1}]')::jsonb),
  ((select id from questions where external_key = 'read-2a'), 'Patients should be told when they are receiving a placebo.', '2', NULL, false, 2, ('[{"dimensionKey":"verbal","points":0}]')::jsonb),
  ((select id from questions where external_key = 'read-2a'), 'Expectation has no measurable effect on clinical outcomes.', '3', NULL, false, 3, ('[{"dimensionKey":"verbal","points":0}]')::jsonb);
