insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('verbal-reasoning', 'Verbal Reasoning', 'Comprehension, analogies, inference and argument evaluation — GRE Verbal / LSAT Logical Reasoning calibre.', 'Verbal Reasoning measures cognitive efficiency in language: how fast and accurately you process arguments, extract logical conclusions, and select the exact word a context demands. It covers four areas — Deductive Reasoning, Critical Reasoning, Reading Comprehension, and Verbal Precision.', 'message-square', (select id from assessment_categories where key = 'language'), ('timed_questionnaire')::assessment_engine_type, ('hard')::assessment_difficulty, 18, 24, false, ('free')::assessment_access, ('published')::assessment_status)
