insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'verbal-reasoning'), 'overall', 0, 30, 'Developing', 'Your results indicate an opportunity to build core deductive and critical-reasoning technique before timed practice will compound — accuracy improvements will move this score faster than speed drills at this stage.', ARRAY['Practice basic syllogisms and modus tollens/modus ponens patterns daily.', 'Slow down on critical reasoning stimuli to fully map the argument before answering.', 'Build vocabulary through active reading rather than word lists alone.']::text[], NULL, 1);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'verbal-reasoning'), 'overall', 31, 50, 'Average', 'You show solid instincts on individual items but inconsistent performance across question types — targeted practice on your weaker category will move this score fastest.', ARRAY['Identify your weakest of the four categories and drill it specifically.', 'Time yourself on practice sets to build comfort under pressure.', 'Practice distinguishing ''must be true'' conclusions from merely plausible ones.']::text[], NULL, 2);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'verbal-reasoning'), 'overall', 51, 70, 'Strong', 'You reliably reach correct conclusions but have room to sharpen either raw processing speed or precision under time pressure — closing that gap is where the largest score gains typically live.', ARRAY['Focus on reducing time-per-question without sacrificing accuracy.', 'Practice eliminating distractor answers quickly in critical reasoning.', 'Sharpen precision with nuanced synonym and analogy drills.']::text[], NULL, 3);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'verbal-reasoning'), 'overall', 71, 85, 'Very Strong', 'You extract logical conclusions and evaluate arguments with strong speed and precision, on par with high-performing graduate program applicants.', ARRAY['Maintain sharpness with periodic timed practice sets.', 'Push into harder, denser reading passages to extend your ceiling.', 'Practice under increasingly compressed time limits.']::text[], NULL, 4);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'verbal-reasoning'), 'overall', 86, 100, 'Exceptional', 'You process language and argument structure at a level consistent with top-decile performance on graduate and executive verbal assessments — fast, accurate, and rarely misled by distractor logic.', ARRAY['Maintain performance with occasional high-difficulty practice.', 'Consider mentoring or teaching reasoning technique to reinforce mastery.', 'Explore adjacent skill areas such as quantitative or abstract reasoning.']::text[], NULL, 5);
